// Writes .github/pc-builder/preview.html: sections/pc-builder.liquid's markup with its schema defaults filled in (a
// minimal stand-in for Liquid, enough for this one section; it fails loudly on any tag it does not know), the theme's
// base CSS and tokens, and the fixture JSON as the data source. Serve the repository root over HTTP (ES modules do not
// load from file://) and open /.github/pc-builder/preview.html; screenshot.cjs does exactly that.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, '../..');
const src = readFileSync(join(repo, 'sections/pc-builder.liquid'), 'utf8');
const schema = JSON.parse(src.split('{% schema %}')[1].split('{% endschema %}')[0]);
const settings = Object.fromEntries(schema.settings.filter((s) => s.id).map((s) => [s.id, s.default ?? '']));
const data = JSON.parse(readFileSync(join(repo, 'config/settings_data.json'), 'utf8').replace(/^\/\*[\s\S]*?\*\/\s*/, ''));
const theme = data.current && typeof data.current === 'object' ? data.current : data.presets?.Default || {};

let body = src.slice(src.indexOf('<div\n  class="pcb page-width"'), src.indexOf('{% schema %}'));
// The store-only parts: the empty-collection branch and the metafield JSON.
body = body.replace(/\n {2}\{%- if coll == blank -%\}[\s\S]*?\n {2}\{%- else -%\}/, '');
body = body.replace(/\s*\{%- endif -%\}\s*<\/div>\s*$/, '\n</div>\n');
body = body.replace(/(<script type="application\/json" data-pcb-overrides>)[\s\S]*?(<\/script>)/, '$1{}$2');
// Conditions that are all true with the defaults.
body = body.replace(/\{%-? if (section\.settings\.\w+ != blank|source != blank|wa_digits != blank) -?%\}/g, '');
body = body.replace(/\{% if section\.settings\.include_os %\} checked\{% endif %\}/g, settings.include_os ? ' checked' : '');
body = body.replace(/\{%-? endif -?%\}/g, '');

const values = {
  uid: 'pcb-preview',
  source: './fixtures/products.json?page={page}',
  budget_min: settings.budget_min,
  budget_max: settings.budget_max,
  budget_default: settings.budget_default,
  'wa_digits | escape': '972500000000',
  'wa_display | escape': '050-0000000',
  'shop.name | escape': 'JOY Mobile',
  "'pc-builder-parser.js' | asset_url": '../../assets/pc-builder-parser.js',
  "'pc-builder-fps.js' | asset_url": '../../assets/pc-builder-fps.js',
};
body = body.replace(/\{\{\s*([^}]+?)\s*\}\}/g, (m, expr) => {
  if (expr in values) return values[expr];
  const s = expr.match(/^section\.settings\.(\w+)(?:\s*\|\s*escape)?$/);
  if (s) return String(settings[s[1]] ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  throw new Error(`make-preview: unknown output ${m}`);
});
const leftover = body.match(/\{%[\s\S]*?%\}/);
if (leftover) throw new Error(`make-preview: unknown tag ${leftover[0]}`);

const tokens = Object.entries(theme)
  .filter(([k, v]) => k.startsWith('color_') && typeof v === 'string')
  .map(([k, v]) => `--${k.replace(/_/g, '-')}: ${v};`)
  .join('\n      ')
  .replace(/--color-(\w)/g, '--color-$1');
const radius = ['button', 'input', 'card', 'badge'].map((k) => `--radius-${k}: ${theme[`radius_${k}`] ?? 10}px;`).join(' ');

const page = `<!doctype html>
<!-- Generated by .github/pc-builder/make-preview.mjs from sections/pc-builder.liquid. Do not edit by hand. -->
<html lang="he" dir="rtl">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <title>מרכיבים מחשב · תצוגה מקדימה</title>
  <link rel="stylesheet" href="../../assets/fonts.css">
  <style>
    :root {
      ${tokens}
      --color-success: var(--color-brand-text);
      --font-body-family: "Assistant", "Assistant Fallback", "Arial Hebrew", Arial, system-ui, sans-serif;
      --font-heading-family: var(--font-body-family);
      --font-body-weight: 400;
      --font-heading-weight: 700;
      --page-width: 1170px;
      --page-gutter: 15px;
      ${radius}
      --header-height: 64px;
    }
    .preview-header { display: flex; align-items: center; height: 64px; padding-inline: 15px; background: var(--color-header-bg); color: var(--color-header-text); font-weight: 800; font-size: 1.25rem; }
  </style>
  <link rel="stylesheet" href="../../assets/base.css">
  <link rel="stylesheet" href="../../assets/pc-builder.css">
  <script>window.theme = { routes: { root: '/', cart: '/cart', cart_add: '/cart/add' } };</script>
  <script type="module" src="../../assets/pc-builder.js"></script>
</head>
<body class="template-page template-page--pc-builder">
  <header class="preview-header">JOY Mobile</header>
  <main id="MainContent" class="main">
${body}
  </main>
</body>
</html>
`;
writeFileSync(join(here, 'preview.html'), page);
console.log('wrote .github/pc-builder/preview.html');
